"""RPC Book Two, Titles Eleven to Fifteen (Arts. 333-367): chastity, civil status, honor, quasi-offenses, final provisions."""

RA10175 = {'t': 'Cybercrime Prevention Act (RA 10175), Sec. 4(c)(4) and Sec. 6', 's': 'Libel committed through a computer system is cyber libel, punished one degree higher; Disini v. Secretary of Justice (2014) upheld it as to the original author only.', 'u': '#/code/ra10175'}
AC08 = {'t': 'Supreme Court Administrative Circular No. 08-2008', 's': 'Guidelines in libel cases: courts may, in their discretion, prefer a fine to imprisonment, depending on the circumstances.', 'u': ''}
RA11222 = {'t': 'Simulated Birth Rectification Act (RA 11222, 2019)', 's': 'Persons who simulated a child’s birth before the law took effect, for the child’s best interest, may rectify the record through administrative adoption and are exempt from criminal, civil and administrative liability.', 'u': ''}
RA7610 = {'t': 'Special Protection of Children Act (RA 7610), Sec. 5(b)', 's': 'Lascivious conduct with a child exploited in prostitution or subjected to other sexual abuse carries a heavier penalty; see People v. Tulagan (2019) for when the Code or RA 7610 applies.', 'u': ''}


def add(n):
    # ------------------------------------------------------------ Title Eleven: chastity
    n(333, 'Adultery: a married woman who has sexual intercourse with a man not her husband, and the man who knows she is married. Each act of intercourse is a separate adultery.',
      k=['The woman is married (even if the marriage is later declared void).', 'She has sexual intercourse with a man not her husband.', 'The man knows she is married (as to his liability).'],
      t=['Only the offended husband can file the complaint, and he must include both guilty parties if both are alive (Art. 344).', 'Consent or pardon by the husband bars prosecution.', 'If the husband was abandoned without justification, the penalty is lower (par. 3).'],
      chk=['married woman', 'knowing her to be married'])
    n(334, 'Concubinage: a husband who (1) keeps a mistress in the conjugal dwelling; (2) has sexual intercourse with a woman not his wife under scandalous circumstances; or (3) cohabits with her in any other place. The concubine is punished with destierro.',
      t=['Concubinage is harder to prove than adultery: a single act of intercourse is not enough unless under scandalous circumstances.', 'The same act may also be psychological violence under RA 9262 (marital infidelity causing mental anguish).'],
      chk=['conjugal dwelling', 'scandalous circumstances', 'destierro'])
    n(335, 'Old rape provision — repealed by RA 8353 (1997). Rape is now Arts. 266-A to 266-D.', chk=['carnal knowledge'])
    n(336, 'Acts of lasciviousness: committing any act of lasciviousness on a person of either sex under any of the circumstances of rape (force or intimidation, deprivation of reason or unconsciousness, fraudulent machination or grave abuse of authority, or the victim’s age or dementia).',
      k=['An act of lasciviousness or lewdness.', 'On another person of either sex.', 'Under any of the circumstances of rape (now Art. 266-A).'],
      t=['The difference from attempted rape is intent: acts that show intent to lie with the victim are attempted rape; lewd acts without that intent are acts of lasciviousness.', 'If the victim is a child exploited in prostitution or subjected to other sexual abuse, RA 7610, Sec. 5(b) applies with a heavier penalty (People v. Tulagan, 2019; Dimakuta v. People, 2015).'],
      d=[{'n': 'Dimakuta v. People', 'c': 'G.R. No. 206513, October 20, 2015 (En Banc)', 'h': 'Where the victim is a child at least twelve but below eighteen and the act is lascivious conduct under RA 7610, the accused should be convicted under RA 7610, Sec. 5(b), which carries the heavier penalty, rather than under Art. 336.', 'r': 'Art. 336 and RA 7610.'}],
      i=[RA7610], chk=['act of lasciviousness', 'either sex'])
    n(337, 'Qualified seduction (as amended by RA 11648): seduction of a minor sixteen and over but under eighteen by a person in public authority, priest, house-servant, domestic, guardian, teacher, or anyone entrusted with the minor’s education or custody; and seduction of one’s sister or descendant, whatever her age or reputation.',
      k=['The victim is sixteen or over but under eighteen (since RA 11648).', 'The offender has carnal knowledge of her.', 'The offender abuses his authority, confidence or relationship (one of the listed persons).'],
      t=['Below sixteen, the act is statutory rape (Art. 266-A(1)(d)).', 'RA 11648 replaced “a virgin over twelve” with “a minor, sixteen and over but under eighteen”; virginity is no longer required in the text.', 'For a sister or descendant, age and virginity do not matter.'],
      chk=['sixteen and over but under eighteen', 'sister or descendant'])
    n(338, 'Simple seduction (as amended by RA 11648): seduction of a minor sixteen and over but under eighteen by means of deceit (typically an unfulfilled promise of marriage).', chk=['by means of deceit'])
    n(339, 'Acts of lasciviousness with the consent of the offended party: lascivious acts by the same persons and under the same circumstances as in qualified and simple seduction (Arts. 337 and 338).', t=['Compare Art. 336 (without consent, under the circumstances of rape).'], chk=['same persons and the same circumstances'])
    n(340, 'Corruption of minors (as amended by BP 92): promoting or facilitating the prostitution or corruption of persons under age to satisfy the lust of another; a public officer or employee (including in GOCCs) also suffers temporary absolute disqualification.', t=['Since BP 92, habituality and abuse of authority are no longer required; a single act suffices.', 'It is the lust of another that must be satisfied; the offender who satisfies his own lust commits another crime.'], chk=['to satisfy the lust of another'])
    n(341, 'White slave trade (as amended by BP 186): engaging in the business of prostitution, profiting by it, or enlisting the services of any other person for prostitution.', t=['Trafficking for sexual exploitation is now mainly prosecuted under RA 9208 as amended, with much heavier penalties.'], chk=['enlist the services of any other person for the purpose of prostitution'])
    n(342, 'Forcible abduction: taking away a woman against her will and with lewd designs; the same penalty if she is under twelve, even if she consents.',
      k=['The person abducted is a woman (of any age, civil status or reputation).', 'She is taken against her will.', 'With lewd designs.'],
      t=['If rape follows, the crime is forcible abduction with rape (complex crime, Art. 48) when the abduction was the means; later rapes are separate crimes.', 'If the purpose is not lewd, the crime may be kidnapping or grave coercion.'],
      chk=['against her will and with lewd designs'])
    n(343, 'Consented abduction: abduction of a virgin over twelve and under eighteen, with her consent and with lewd designs.', t=['RA 11648 did not amend this article; it still reads “over twelve and under eighteen”.'], chk=['over twelve and under eighteen'])
    n(344, 'Private crimes: adultery and concubinage are prosecuted only upon complaint of the offended spouse, against both guilty parties if alive, and not if he or she consented or pardoned them. Seduction, abduction and acts of lasciviousness need a complaint of the offended party, her parents, grandparents or guardian, and are extinguished by express pardon; marriage of the offender with the offended party extinguishes the action or penalty, also as to co-principals, accomplices and accessories.',
      t=['Rape is no longer a private crime (RA 8353).', 'The complaint requirement is jurisdictional in the sense that the State cannot proceed without it.', 'Pardon must come before the institution of the criminal action.'],
      chk=['offended spouse', 'expressly pardoned'])
    n(345, 'Civil liability in crimes against chastity: indemnifying the offended woman, acknowledging the offspring (unless the law prevents it), and supporting the offspring. In adultery and concubinage, only indemnity.', chk=['acknowledge the offspring'])
    n(346, 'Ascendants, guardians, curators, teachers and others who, by abuse of authority or confidential relationship, cooperate as accomplices in crimes against chastity are punished as principals.', chk=['punished as principals'])

    # ------------------------------------------------------------ Title Twelve: civil status
    n(347, 'Simulation of births, substitution of one child for another, and concealment or abandonment of a legitimate child with intent to cause it to lose its civil status; heavier for a public officer or a physician or surgeon who cooperates.',
      t=['RA 11222 (2019) allows rectification of simulated births made before it took effect, without criminal liability, if done for the child’s best interest.'],
      i=[RA11222], chk=['simulation of births'])
    n(348, 'Usurpation of civil status: assuming the civil status of another (e.g., pretending to be a legitimate child or the spouse) to defraud the offended party or his heirs.', chk=['usurp the civil status of another'])
    n(349, 'Bigamy: contracting a second or subsequent marriage before the first has been legally dissolved, or before the absent spouse has been declared presumptively dead in proper proceedings.',
      k=['The offender is legally married.', 'The first marriage has not been legally dissolved, or the absent spouse has not been declared presumptively dead.', 'He or she contracts a second or subsequent marriage.', 'The second marriage has all the essential requisites for validity (but for the bigamy).'],
      t=['Under Art. 40 of the Family Code a judicial declaration of nullity is needed before remarrying. But since Pulido v. People (2021, En Banc), a judicial declaration that the first marriage was void ab initio — even one obtained after the second marriage — is a valid defense.', 'A voidable first marriage, unannulled, still supports bigamy.', 'Prescription runs from discovery by the offended spouse or the authorities.'],
      d=[{'n': 'Pulido v. People', 'c': 'G.R. No. 220149, July 27, 2021 (En Banc)', 'h': 'The Court held that a void ab initio first marriage, judicially declared void even after the second marriage was contracted, is a valid defense in bigamy; it abandoned earlier rulings that required the declaration before the second marriage for purposes of the criminal case.', 'r': 'The current rule on void first marriages.'}],
      chk=['before the former marriage has been legally dissolved', 'declared presumptively dead'])
    n(350, 'Marriage contrary to law: contracting a marriage knowing that the requirements of law were not complied with, or that the marriage is disregarded by a legal impediment (not covered by bigamy); heavier if consent was obtained by violence, intimidation or fraud.', chk=['legal impediment'])
    n(351, 'Premature marriages — repealed by RA 10655 (2015).', chk=['three hundred and one days'])
    n(352, 'Performance of an illegal marriage ceremony by priests, ministers or civil authorities, punished under the Marriage Law.', chk=['illegal marriage ceremony'])

    # ------------------------------------------------------------ Title Thirteen: honor
    n(353, 'Libel: a public and malicious imputation of a crime, a vice or defect (real or imaginary), or any act, omission, condition, status or circumstance tending to cause the dishonor, discredit or contempt of a natural or juridical person, or to blacken the memory of one who is dead.',
      k=['An imputation of a crime, vice, defect, act, omission, condition, status or circumstance.', 'Publication (communication to a third person).', 'Identity of the person defamed (identifiable, even if not named).', 'Malice (presumed from a defamatory imputation, Art. 354).'],
      t=['The imputation need not be true or false; truth is a defense only as allowed by Art. 361.', 'A juridical person, and the memory of the dead, can be defamed.'],
      i=[RA10175, AC08], chk=['public and malicious imputation', 'memory of one who is dead'])
    n(354, 'Every defamatory imputation is presumed malicious, even if true, unless good intention and justifiable motive are shown, except in privileged communications: (1) a private communication made in the performance of a legal, moral or social duty; (2) a fair and true report, without comments, of official proceedings that are not confidential.',
      t=['In privileged communications, malice is not presumed; the complainant must prove malice in fact.', 'Fair comment on matters of public interest about public officers and public figures is also protected (actual malice standard for public figures).'],
      chk=['presumed to be malicious', 'legal, moral or social duty'])
    n(355, 'Libel by writing, printing, lithography, engraving, radio, phonograph, painting, theatrical exhibition, cinematographic exhibition or similar means: prisión correccional minimum to medium, or a fine (adjusted by RA 10951), or both, besides the civil action.',
      t=['Online libel is cyber libel under RA 10175, one degree higher, and prescribes in one year from discovery (Causing v. People, 2023).'],
      i=[RA10175, AC08], chk=['radio', 'cinematographic exhibition'])
    n(356, 'Threatening to publish a libel concerning a person or his family, or offering to prevent its publication, for compensation (blackmail).', chk=['offer to prevent'])
    n(357, 'Prohibited publication of acts referred to in the course of official proceedings: a reporter, editor or manager who publishes facts connected with the private life of another that offend his honor, virtue and reputation, even under cover of reporting official proceedings (the “gag law”).', chk=['private life of another'])
    n(358, 'Slander (oral defamation): grave slander — arresto mayor maximum to prisión correccional minimum; otherwise, arresto menor or a fine.', t=['Whether slander is grave depends on the words, the parties’ social standing, and the circumstances, including the heat of anger.'], chk=['Oral defamation'])
    n(359, 'Slander by deed: an act that casts dishonor, discredit or contempt upon another in the presence of others (e.g., a slap to humiliate); serious or not, by the nature of the act.', t=['If the act is done to cause injury, it is physical injuries or maltreatment (Art. 266); if to dishonor, slander by deed.'], chk=['dishonor, discredit or contempt'])
    n(360, 'Persons responsible and venue (as amended by RA 4363): whoever publishes or causes publication; authors, editors and business managers. Criminal and civil actions for written defamation are filed in the court of the province or city where the libelous article is printed and first published, or where an offended party actually resided at the time (with special rules for public officers); the civil action goes to the same court.',
      t=['Venue in libel is jurisdictional in criminal cases: the information must allege the facts that establish it.', 'Courts of First Instance are now the Regional Trial Courts, which have exclusive original jurisdiction over libel.'],
      chk=['printed and first published', 'actually resides'])
    n(361, 'Proof of truth: truth is admissible and acquits if the imputation was published with good motives and justifiable ends; truth of an imputed crime is a defense, but truth of other imputations is a defense only when the offended party is a public officer and the act relates to official duties.', chk=['good motives and for justifiable ends'])
    n(362, 'Libelous remarks or comments connected with privileged matter (Art. 354) are not exempt if made with malice.', chk=['if made with malice'])
    n(363, 'Incriminating an innocent person: performing an act (not perjury) that directly incriminates or imputes to an innocent person the commission of a crime (planting evidence).', t=['If done through false testimony, the crime is perjury or false testimony; planting of drugs or firearms is also punished by special laws (RA 9165, Sec. 29; RA 10591).'], chk=['directly incriminate or impute to an innocent person'])
    n(364, 'Intriguing against honor: any intrigue whose principal purpose is to blemish the honor or reputation of a person, when it is not libel or slander (e.g., spreading gossip whose source cannot be traced).', chk=['blemish the honor or reputation'])

    # ------------------------------------------------------------ Title Fourteen: quasi-offenses
    n(365, 'Imprudence and negligence: reckless imprudence (voluntary act, without malice, from inexcusable lack of precaution) and simple imprudence (lack of precaution where the damage is not immediate or the danger not clearly manifest). The penalty depends on whether the act, if intentional, would be a grave, less grave or light felony; failure to help the injured on the spot raises it.',
      k=['Reckless imprudence: (1) a voluntary act; (2) without malice; (3) material damage results; (4) from inexcusable lack of precaution, considering the person’s employment, intelligence, physical condition and other circumstances.', 'Simple imprudence: the damage impending is not immediate, or the danger not clearly manifest.'],
      t=['Reckless imprudence is a single crime: its several consequences (homicide, injuries, damage) do not make several offenses. A conviction or acquittal for one consequence bars prosecution for the others (Ivler v. Modesto-San Pedro).', 'The court is not bound by the rules of Art. 64 in fixing the penalty.'],
      d=[{'n': 'Ivler v. Modesto-San Pedro', 'c': 'G.R. No. 172716, November 17, 2010', 'h': 'Reckless imprudence is a distinct crime, not a mode of committing other crimes; a driver convicted of reckless imprudence resulting in slight physical injuries could not be tried again for reckless imprudence resulting in homicide and damage to property from the same act (double jeopardy).', 'r': 'Quasi-offense as a single crime.'}],
      chk=['reckless imprudence', 'simple imprudence', 'lend on the spot'])

    # ------------------------------------------------------------ Title Fifteen: final provisions
    n(366, 'Felonies committed before the Code took effect are punished under the laws then in force, without prejudice to Art. 22 (retroactivity of penal laws favorable to the accused).', chk=['article 22'])
    n(367, 'Repealing clause: the old Penal Code, the Provisional Law, and the Acts listed are repealed, except as provided in Art. 366.', chk=['repealed'])
